contract InvMutTest {
    C c;

    constructor() { c = new C(0, "", ""); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    receive() external payable {}

    function run(uint256 value) public {
        uint256 callerBalance = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;
        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.burn(value); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint256 supplyAfter = c.totalSupply(); if (__ESBMC_reverted()) return;

        assert(
            reverted
                ? value > callerBalance
                : supplyAfter == supplyBefore - value
        );
    }
}

